from kd_common import *
i=11
Z=lambda q,a:[('z',q),('b',a)]
def langbar():
    d=[('Kannaḍa',30.9,'#c0392b'),('Malayāḷam',20.8,'#2a9d6f'),('Kodava',14.9,'#1d4f8a'),('Tuḷu',8.9,'#e0a800'),('Are',5.8,'#6a3d9a'),('Yerava',4.7,'#8a5a2a'),('Tamiḻ',4.2,'#d36a9a'),('others',9.8,'#9a9a9a')]
    o=''; y=20
    for n,v,c in d:
        o+=f'<rect x="130" y="{y}" width="{v*12:.0f}" height="20" fill="{c}"/>'+T(70,y+14,n,10); y+=26
    return o+T(380,236,'first languages, roughly in order (census, rounded)',9)
def basket(): return '<path d="M-24 -30 h48 l-6 30 h-36z" fill="#c9a66a"/><path d="M-20 -20 h40 M-18 -10 h36" stroke="#8a6a3a" stroke-width="2"/>'
def box(): return '<rect x="-30" y="-30" width="60" height="30" fill="#7a3b1f"/><rect x="-30" y="-36" width="60" height="8" fill="#5a2a10"/><circle cy="-15" r="4" fill="#e0a800"/>'
fw=foreword(i,['Kodagu is not only the Kodavas. The district’s people speak Kannaḍa, Malayāḷam, Kodava, Tuḷu, Are, Yerava and more, and around twenty communities besides the Kodavas speak Kodava takk at home, keep ainmanes, wear the kupya and dance at the same festivals. The festivals in this series belong to all of them in different ways.',
 'This last part introduces the main communities: the Kodava-speaking groups such as the Amma Kodavas, Airis, Kembaṭṭis and Meda; the Kodagu Gowdas who speak Are bhāṣe; the forest peoples; the Kodava Maaple Muslims; and the newer neighbours.',
 'Start of the series: '+L('/kodagu/kodavas/','The Kodavas')+'. All parts: '+L('/kodagu/','Kodagu')+'. The coast: '+L('/tulunadu/','Tulu Nadu')+'.'],Z('Is “Kodava” a people or a language?','Both. The Kodava people, and the Kodava language that many communities speak.'))
gl=glance([('Languages','Kannaḍa, Malayāḷam, Kodava, Tuḷu, Are, Yerava, Tamiḻ and more'),('Kodava speakers','Kodavas and about 18–22 other communities'),('Some of them','Amma Kodava, Heggaḍe, Airi, Koyava, Banna, Kembaṭṭi, Meda, Maaple'),('Are speakers','Kodagu (Arebhāṣe) Gowdas'),('Forest peoples','Yerava, Kuruba and others'),('Muslims','Kodava Maaple, Beary, Mappiḷa and others'),('Shared','Ainmanes, dress, Igguthappa, festivals'),('History','1837 revolt with many communities'),('Newer','Tibetans at Bylakuppe; migrants')],
 S('People in varied dress in a row before hills',hills(560,110,'#5a9a5a')+''.join(g(60+k*74,215,1,f()) for k,f in enumerate([kodava_man,kodava_woman,lambda:person('#e0a800'),lambda:person('#2a9d6f'),lambda:kodava_man('#f4f1ea'),lambda:person('#c0392b'),lambda:person('#8a5a2a')])),'#d8e8f0',215),Z('Do they all celebrate Puttari?','Most communities do, each in its own way.'),'Many peoples, <b>one hill country</b>.')
lang=reading('languages','LANGUAGES','Who speaks what',svg(560,250,'Bar chart of first languages in Kodagu',langbar()),
 ['<b>Mixed.</b> Kannaḍa is the most common first language, followed by Malayāḷam, Kodava, Tuḷu, Are, Yerava and Tamiḻ.','<b>Kodava takk.</b> Spoken not only by the Kodavas but by many other communities.','<b>Are bhāṣe.</b> The speech of the Kodagu Gowdas, close to Kannaḍa.','<b>Malayāḷam.</b> Many families have Kerala roots, old and new.','<b>Kannaḍa.</b> The official language and the common tongue.'],Z('Which language for the festivals?','Kodava songs, Kannaḍa notices, Malayāḷam at the tea stall.'),'Half a dozen tongues <b>in one district</b>.')
kodsp=reading('kodava-speaking','KODAVA-SPEAKING COMMUNITIES','About twenty groups',S('A circle of family houses, all with lamps',''.join(g(80+k*100,215,.8,ainmane(90))+g(80+k*100,150,.3,hanging_lamp()) for k in range(5)),'#fff3cf',215),
 ['<b>Many.</b> Besides the Kodavas, around 18 to 22 communities speak Kodava takk; lists differ.','<b>Names.</b> They include the Amma Kodava, Heggaḍe (Peggaḍe), Airi, Koyava, Koleya, Golla, Kodava Nāyar, Banna, Madivāḷa, Hajāma (Nainda), Kaniya, Panika, Māliya, Marangi, Kembaṭṭi, Meda and the Kodava Maaple.','<b>Ainmanes.</b> Most have ancestral houses.','<b>Culture.</b> They follow Kodava culture in dress, festivals and rites, each with its own customs.','<b>Academy.</b> The Karnataka Kodava Sahitya Academy has documented them.'],Z('Are they Kodavas?','They are Kodava-speaking. “Kodava” as a community name usually means the dominant group.'),'One language, <b>many houses</b>.')
amma=reading('amma','AMMA KODAVAS','The people of the mother',S('An elder in white beside a river shrine',g(180,215,1.6,kodava_man('#f4f1ea'))+g(380,210,1.2,devi(sari='#4aa3df',items=('pot',)))+'<path d="M300 220 C380 200 460 230 540 210" stroke="#4aa3df" stroke-width="10" fill="none"/>','#d8e8f0',215),
 ['<b>Small.</b> The Amma Kodavas are a small community.','<b>Priests.</b> They are believed to have once been principal priests (arcakas) of Kodagu.','<b>Name.</b> One of their spokesmen says the name comes from <b>Amma</b>, Mother Kāverī, by whose mercy their ancestors were restored: they call themselves <b>Ammaṅga</b>.','<b>Origins.</b> Several origin stories are told; the community itself disputes some of them.','<b>Customs.</b> They follow Kodava dress and many rites, with their own differences.'],Z('Which story is right?','The community’s own account deserves first hearing.'),'Named for <b>the mother</b>.')
crafts=cards('crafts','HANDS OF KODAGU','Smiths, carpenters, weavers, drummers',fig_row('A carved chest, a basket, a drum and a knife',[(box(),1.2),(basket(),1.2),(dudi(),1),('<path d="M-30 0 l50 -8" stroke="#9a9a9a" stroke-width="6"/><path d="M-30 0 h-10" stroke="#5a3a1a" stroke-width="7"/>',1.2)],['sandūka','basket','duḍi','oḍi katti'],gy=150),
 [('🔨','Airi','Carpenters and village smiths; makers of Kodava ornaments, weapons and the wooden chest (sandūka). Airira is a common family name.'),('🧺','Meda','Basket and mat weavers, and drummers of the vālaga.'),('🌾','Kembaṭṭi','Household workers and labourers of old estates, with their own festival at Pannaṅgālatamme.'),('🎭','Banna, Maleya','Performers of kōla rites at village temples.'),('✂️','Hajāma, Madivāḷa','Barbers and washermen with ritual roles.'),('🌿','Māliya','Known for herbal medicine.')],None,'The crafts <b>behind the festivals</b>.',intro='Traditional occupations are named here for history; today members of every community work in every field.')
gowda=reading('gowdas','KODAGU GOWDAS','Speakers of Are bhāṣe',S('A Gowda family in traditional dress before an ainmane',g(280,210,1.4,ainmane())+g(130,215,1.2,kodava_man('#f4f1ea'))+g(430,215,1.2,kodava_woman('#2a9d6f')),'#d8e8c8',215),
 ['<b>Who.</b> The Arebhāṣe Gowdas, or Kodagu Gowdas, are a community of Kodagu and Dakṣiṇa Kannaḍa.','<b>Language.</b> They speak <b>Are bhāṣe</b>.','<b>Shared.</b> Their traditional dress is close to the Kodava; many revere Igguthappa and keep Puttari and Kakkaḍa customs.','<b>Gowda Samāja.</b> Gowda Samājas hold their own Puttari celebrations.','<b>1837.</b> <b>Guḍḍemane Appaiah Gowda</b> led, with men of many communities, the armed revolt of 1837 against the British across Kodagu and Dakṣiṇa Kannaḍa.'],Z('Rivals or neighbours?','Neighbours. Like all neighbours, they sometimes disagree, and they share the same festivals.'),'Neighbours <b>in dress and faith</b>.')
forest=reading('forest','FOREST PEOPLES','Yerava, Kuruba and others',S('A hut at the forest edge, people carrying honey and bamboo',g(150,215,2,tree('#2f6a3a'))+g(300,210,1.2,'<path d="M-40 0 L0 -50 L40 0z" fill="#9a7a4a"/>')+g(430,215,1.1,person('#8a5a2a'))+g(470,180,.6,bees()),'#d8e8c8',215),
 ['<b>Yerava.</b> The Yerava speak their own language; many worked on estates.','<b>Kuruba.</b> Forest communities such as the Jēnu and Beṭṭa Kurubas live near Nāgarahoḷe and the southern forests.','<b>Knowledge.</b> They hold deep knowledge of forest, honey, herbs and animals.','<b>Challenges.</b> Land rights, wages and displacement from forests are long-running issues.','<b>Festivals.</b> They keep their own festivals and gods, and also take part in district ones.'],Z('Are they part of Kodava culture?','They are part of Kodagu’s culture, with their own traditions.'),'The forest’s <b>own people</b>.')
maaple=reading('maaple','KODAVA MAAPLE','Muslims with clan names',S('A man in kupya and cap beside a small mosque and an ainmane',g(160,215,1.6,kodava_man())+'<rect x="146" y="132" width="28" height="8" fill="#f4f1ea"/>'+g(330,210,1.2,'<rect x="-40" y="-40" width="80" height="40" fill="#f4f1ea"/><ellipse cy="-48" rx="22" ry="16" fill="#2a9d6f"/>')+g(470,210,.9,ainmane(110)),'#d8e8f0',215),
 ['<b>Who.</b> The Kodava Maaple, also called Jamma Maaple, are a Muslim community of Kodagu.','<b>Language.</b> They speak Kodava takk.','<b>Clans.</b> Many keep ancestral clan names, like the Kodavas.','<b>Dress.</b> Traditionally the men wore Kodava dress.','<b>Others.</b> Kodagu’s other Muslims include Bearys, Mappiḷas, Syeds and Sheikhs.'],Z('Muslims who follow Kodava custom?','In dress, language and clan life, yes. Faith is Islam; culture is Kodagu.'),'Kodava in speech, <b>Muslim in faith</b>.')
new=reading('new','NEWER NEIGHBOURS','Tibetans, migrants, estate workers',S('A Tibetan monastery roof and prayer flags near coffee estates',g(280,200,1.4,'<rect x="-80" y="-50" width="160" height="50" fill="#c0392b"/><path d="M-100 -50 L0 -96 L100 -50z" fill="#e0a800"/>')+''.join(f'<rect x="{60+k*22}" y="60" width="16" height="12" fill="{["#1d4f8a","#f4f1ea","#c0392b","#2a9d6f","#e0a800"][k%5]}"/>' for k in range(8))+g(480,210,1,coffee()),'#d8e8f0',215),
 ['<b>Bylakuppe.</b> Tibetan settlements near Kuśālanagar, founded from the 1960s, are among the largest in India.','<b>Estate workers.</b> Workers from other districts and states keep the coffee estates going.','<b>Kerala ties.</b> Malayāḷi families have lived in Kodagu for generations.','<b>Tuḷu speakers.</b> Billavas, Mogaveeras, Bunts and others came from the coast.','<b>Change.</b> Kodagu’s mix keeps changing; the festivals adapt.'],Z('Do Tibetans celebrate Puttari?','Not as their own festival, but Kodagu is their home now too.'),'A district <b>that keeps changing</b>.')
endp=end(i,['<b>Languages.</b> Kannaḍa, Malayāḷam, Kodava, Tuḷu, Are, Yerava and more.','<b>Kodava speakers.</b> About twenty communities besides the Kodavas.','<b>Neighbours.</b> Kodagu Gowdas, forest peoples, Kodava Maaple, newer arrivals.','<b>Series.</b> Twelve parts on Kodagu’s culture and festivals.'],'Return to the start: The Kodavas.','Many peoples, one hill country')
src=sources([('Population and language:','Wikipedia “Kodagu district” (language shares, Kodava-speaking groups, Arebhāṣe Gowdas, Guḍḍemane Appaiah Gowda); Wikipedia “Kodava Maaple”.'),('Communities:','Kodagu First on Kodava-speaking communities; Sahapedia interview with Kasturi Govindammayya (Amma Kodavas); Deccan Herald on the Airi sandūka makers and Kembaṭṭi traditions; Star of Mysore (Gowda Samāja Puttari).')],'community lists vary between 18 and 23; traditional occupations are historical; forest community issues are summarised generally.','Community names romanised simply.')
finish(i,'PART 12 OF 12 · LANGUAGES · CLANS · NEIGHBOURS',covart('A row of people in varied dress before misty hills',hills(440,100,'#5a9a5a')+''.join(g(60+k*64,190,.9,f()) for k,f in enumerate([kodava_man,kodava_woman,lambda:person('#e0a800'),lambda:person('#2a9d6f'),lambda:kodava_man('#f4f1ea'),lambda:person('#c0392b')]))),'Many peoples, one hill country',
 '<b>Kodagu’s communities</b>: the languages of the district, the twenty Kodava-speaking groups, the Amma Kodavas, Airis and Meda, the <b>Kodagu Gowdas</b>, the forest peoples, the Kodava Maaple and newer neighbours.',
 'Kodagu’s communities explained and illustrated: the district’s languages, Kodava-speaking communities, Amma Kodavas, Airi, Meda and Kembaṭṭi, Arebhāṣe Gowdas, Yerava and Kuruba, Kodava Maaple and Bylakuppe Tibetans.',
 [fw,gl,lang,kodsp,amma,crafts,gowda,forest,maaple,new,endp,src])
